7	// CanonicalKey normalizes a model string for fuzzy matching.
8	//
9	// The normal form:
10	// - trims whitespace
11	// - strips a single leading vendor namespace before the first slash
12	// - lowercases the result
13	// - removes all non-alphanumeric characters
14	//
15	// This makes inputs such as "qwen/qwen3.6", "QWEN3.6", and
16	// "Qwen-3.6-27b-MLX-8bit" comparable under the same substring matching
17	// rules.
18	func CanonicalKey(s string) string {
19		s = strings.TrimSpace(s)
20		if slash := strings.Index(s, "/"); slash > 0 {
21			s = s[slash+1:]
22		}
23		s = strings.ToLower(s)
24		var b strings.Builder
25		b.Grow(len(s))
26		for _, r := range s {
27			switch {
28			case r >= 'a' && r <= 'z':
29				b.WriteRune(r)
30			case r >= '0' && r <= '9':
31				b.WriteRune(r)
32			}
33		}
34		return b.String()
35	}
36	
37	// Match returns the pool entries whose canonical key contains the canonical
38	// key for requested as a substring. The pool order is preserved.
39	func Match(requested string, pool []string) []string {
40		key := CanonicalKey(requested)
41		if key == "" || len(pool) == 0 {
42			return nil
43		}
44		matches := make([]string, 0, len(pool))
45		for _, candidate := range pool {
46			if candidate == "" {
47				continue
48			}
49			if strings.Contains(CanonicalKey(candidate), key) {
50				matches = append(matches, candidate)
51			}
52		}
53		if len(matches) == 0 {
54			return nil
55		}
56		return matches
57	}
