package modelref

import (
	"fmt"
	"strings"
)

// ModelRef is the canonical model identity used as the cache key and routing
// surface: <provider>/<id>.
// Provider is a lowercase slug (letters, digits, hyphens, dots; no slashes).
// ID preserves the provider's original casing and may contain slashes
// (e.g. openrouter sub-paths like "qwen/qwen3.6-27b").
type ModelRef struct {
	Provider string
	ID       string
}

// Parse splits s on the first "/" into Provider and ID.
//
//	"openrouter/qwen/qwen3.6-27b"  → {Provider:"openrouter", ID:"qwen/qwen3.6-27b"}
//	"vidar-ds4/deepseek-v4-flash"  → {Provider:"vidar-ds4", ID:"deepseek-v4-flash"}
func Parse(s string) (ModelRef, error) {
	idx := strings.IndexByte(s, '/')
	if idx < 0 {
		return ModelRef{}, fmt.Errorf("modelref: no '/' in %q", s)
	}
	r := ModelRef{
		Provider: s[:idx],
		ID:       s[idx+1:],
	}
	if err := r.Validate(); err != nil {
		return ModelRef{}, err
	}
	return r, nil
}

// String returns "<provider>/<id>".
func (r ModelRef) String() string {
	return r.Provider + "/" + r.ID
}

// Validate checks that Provider and ID are non-empty and that Provider
// satisfies the slug rules (lowercase letters, digits, hyphens, dots; no slashes).
func (r ModelRef) Validate() error {
	if r.Provider == "" {
		return fmt.Errorf("modelref: provider is empty")
	}
	if r.ID == "" {
		return fmt.Errorf("modelref: id is empty")
	}
	for i, c := range r.Provider {
		if !isProviderRune(c) {
			return fmt.Errorf("modelref: provider %q has invalid character %q at position %d", r.Provider, c, i)
		}
	}
	return nil
}

func isProviderRune(c rune) bool {
	return (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '.'
}

package modelref

import (
	"testing"
)

func TestParse(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		wantRef ModelRef
		wantErr bool
	}{
		{
			name:    "simple",
			input:   "openrouter/claude-3-opus",
			wantRef: ModelRef{Provider: "openrouter", ID: "claude-3-opus"},
		},
		{
			name:    "id with slashes (sub-path)",
			input:   "openrouter/qwen/qwen3.6-27b",
			wantRef: ModelRef{Provider: "openrouter", ID: "qwen/qwen3.6-27b"},
		},
		{
			name:    "id with multiple slashes",
			input:   "openrouter/anthropic/claude-opus-4-5",
			wantRef: ModelRef{Provider: "openrouter", ID: "anthropic/claude-opus-4-5"},
		},
		{
			name:    "provider with hyphen",
			input:   "vidar-ds4/deepseek-v4-flash",
			wantRef: ModelRef{Provider: "vidar-ds4", ID: "deepseek-v4-flash"},
		},
		{
			name:    "provider with dot",
			input:   "sindri.club/llama3-70b",
			wantRef: ModelRef{Provider: "sindri.club", ID: "llama3-70b"},
		},
		{
			name:    "provider with digits",
			input:   "ollama3/llama3",
			wantRef: ModelRef{Provider: "ollama3", ID: "llama3"},
		},
		{
			name:    "no slash → error",
			input:   "openrouter",
			wantErr: true,
		},
		{
			name:    "empty provider (leading slash)",
			input:   "/claude-3",
			wantErr: true,
		},
		{
			name:    "empty id (trailing slash)",
			input:   "openrouter/",
			wantErr: true,
		},
		{
			name:    "empty string",
			input:   "",
			wantErr: true,
		},
		{
			name:    "provider with uppercase letter",
			input:   "OpenRouter/model",
			wantErr: true,
		},
		{
			name:    "provider with space",
			input:   "open router/model",
			wantErr: true,
		},
		{
			name:    "provider with underscore",
			input:   "open_router/model",
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := Parse(tt.input)
			if tt.wantErr {
				if err == nil {
					t.Errorf("Parse(%q): expected error, got %v", tt.input, got)
				}
				return
			}
			if err != nil {
				t.Errorf("Parse(%q): unexpected error: %v", tt.input, err)
				return
			}
			if got != tt.wantRef {
				t.Errorf("Parse(%q) = %+v, want %+v", tt.input, got, tt.wantRef)
			}
		})
	}
}

func TestString(t *testing.T) {
	r := ModelRef{Provider: "openrouter", ID: "qwen/qwen3.6-27b"}
	got := r.String()
	want := "openrouter/qwen/qwen3.6-27b"
	if got != want {
		t.Errorf("String() = %q, want %q", got, want)
	}
}

func TestStringRoundtrip(t *testing.T) {
	inputs := []string{
		"openrouter/claude-3-opus",
		"openrouter/qwen/qwen3.6-27b",
		"vidar-ds4/deepseek-v4-flash",
		"ollama/llama3:8b",
	}
	for _, s := range inputs {
		r, err := Parse(s)
		if err != nil {
			continue // skip invalid
		}
		if got := r.String(); got != s {
			t.Errorf("Parse(%q).String() = %q, want %q", s, got, s)
		}
	}
}

func TestValidate(t *testing.T) {
	tests := []struct {
		name    string
		ref     ModelRef
		wantErr bool
	}{
		{"valid simple", ModelRef{Provider: "openrouter", ID: "claude"}, false},
		{"valid with dot", ModelRef{Provider: "sindri.club", ID: "model"}, false},
		{"valid with hyphen", ModelRef{Provider: "vidar-ds4", ID: "model"}, false},
		{"empty provider", ModelRef{Provider: "", ID: "model"}, true},
		{"empty id", ModelRef{Provider: "openrouter", ID: ""}, true},
		{"provider with slash", ModelRef{Provider: "open/router", ID: "model"}, true},
		{"provider uppercase", ModelRef{Provider: "OpenRouter", ID: "model"}, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := tt.ref.Validate()
			if tt.wantErr && err == nil {
				t.Errorf("Validate(%+v): expected error", tt.ref)
			}
			if !tt.wantErr && err != nil {
				t.Errorf("Validate(%+v): unexpected error: %v", tt.ref, err)
			}
		})
	}
}

package discoverycache

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"syscall"
	"time"
)

type lockPayload struct {
	PID       int       `json:"pid"`
	StartedAt time.Time `json:"started_at"`
}

// acquireLock acquires the tier-1 brief mutation lock for s. Returns a release
// func on success. Polls up to lockAcquisitionTimeout, recovering stale locks
// whose owner PID is dead (mirrors acquireMatrixLock semantics from
// cmd/bench/matrix.go:1222).
func (c *Cache) acquireLock(s Source) (func(), error) {
	lockPath := c.lockPath(s)
	payload := lockPayload{PID: os.Getpid(), StartedAt: time.Now().UTC()}
	raw, _ := json.Marshal(payload)

	deadline := time.Now().Add(lockAcquisitionTimeout)
	for {
		f, err := os.OpenFile(lockPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600) // #nosec G304
		if err == nil {
			if _, werr := f.Write(raw); werr != nil {
				_ = f.Close()
				_ = os.Remove(lockPath)
				return nil, werr
			}
			if cerr := f.Close(); cerr != nil {
				_ = os.Remove(lockPath)
				return nil, cerr
			}
			return func() { _ = os.Remove(lockPath) }, nil
		}
		if !errors.Is(err, os.ErrExist) {
			return nil, err
		}
		// Recover stale lock if owner is dead.
		if existing, rerr := readLockPayload(lockPath); rerr == nil && !processAlive(existing.PID) {
			_ = os.Remove(lockPath)
			continue
		}
		if time.Now().After(deadline) {
			return nil, fmt.Errorf("discoverycache: timed out acquiring lock for %s/%s", s.Tier, s.Name)
		}
		time.Sleep(lockPollInterval)
	}
}

func readLockPayload(path string) (lockPayload, error) {
	data, err := os.ReadFile(path) // #nosec G304
	if err != nil {
		return lockPayload{}, err
	}
	var p lockPayload
	if err := json.Unmarshal(data, &p); err != nil {
		return lockPayload{}, err
	}
	return p, nil
}

func processAlive(pid int) bool {
	if pid <= 0 {
		return false
	}
	err := syscall.Kill(pid, 0)
	return err == nil || errors.Is(err, syscall.EPERM)
}

package discoverycache

import (
	"encoding/json"
	"errors"
	"os"
	"time"
)

// refreshMarker is the tier-2 long-lived marker written when a refresh is
// in progress. Other processes inspect it to decide whether to wait or return
// stale data. JSON payload mirrors ADR-012 §3.
type refreshMarker struct {
	PID       int       `json:"pid"`
	StartedAt time.Time `json:"started_at"`
	Deadline  time.Time `json:"deadline"`
}

// readMarker reads the .refreshing file for s. Returns (nil, nil) if absent.
func readMarker(path string) (*refreshMarker, error) {
	data, err := os.ReadFile(path) // #nosec G304
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var m refreshMarker
	if err := json.Unmarshal(data, &m); err != nil {
		// Corrupt marker — treat as absent so the caller can reclaim.
		return nil, nil
	}
	return &m, nil
}

// writeMarker writes m to path, overwriting any existing file.
func writeMarker(path string, m *refreshMarker) error {
	data, err := json.Marshal(m)
	if err != nil {
		return err
	}
	// Overwrite (not O_EXCL) because claimRefresh already holds the tier-1 lock.
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600) // #nosec G304
	if err != nil {
		return err
	}
	if _, werr := f.Write(data); werr != nil {
		_ = f.Close()
		_ = os.Remove(path)
		return werr
	}
	return f.Close()
}

// isStale returns true when m should be treated as an orphan.
// A marker is stale when: the owner PID is dead, OR now > deadline + 2×RefreshDeadline.
// The deadline-based check is the safety net for PID reuse (ADR-012 §3, §10 test).
func isStale(s Source, m *refreshMarker) bool {
	if m == nil {
		return true
	}
	if !processAlive(m.PID) {
		return true
	}
	// 2× multiplier per ADR-012 "Marker staleness threshold = 2 × refresh deadline"
	threshold := s.RefreshDeadline * stalenessMultiplier
	return time.Now().After(m.Deadline.Add(threshold))
}

// isMarkerActiveForPrune is a conservative check used only by Prune when the
// source's RefreshDeadline is unknown. A marker is active if its PID is alive
// and the deadline itself has not passed (no multiplier).
func isMarkerActiveForPrune(m *refreshMarker) bool {
	if m == nil {
		return false
	}
	return processAlive(m.PID) && time.Now().Before(m.Deadline)
}

package discoverycache

import (
	"os"
	"path/filepath"
)

// atomicWrite writes data to path using the tmp→fsync→rename pattern so
// readers never observe a partial write. Mirrors the pattern in
// internal/harnesses/claude/quota_cache.go:WriteClaudeQuota.
func atomicWrite(path string, data []byte) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return err
	}
	tmp := path + ".tmp"
	f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600) // #nosec G304
	if err != nil {
		return err
	}
	if _, werr := f.Write(data); werr != nil {
		_ = f.Close()
		_ = os.Remove(tmp)
		return werr
	}
	if serr := f.Sync(); serr != nil {
		_ = f.Close()
		_ = os.Remove(tmp)
		return serr
	}
	if cerr := f.Close(); cerr != nil {
		_ = os.Remove(tmp)
		return cerr
	}
	if rerr := os.Rename(tmp, path); rerr != nil {
		_ = os.Remove(tmp)
		return rerr
	}
	_ = os.Chmod(path, 0o600) // best-effort: ensure mode even if older file existed
	return nil
}

// Package discoverycache implements the per-source on-disk cache described in
// ADR-012. It provides a two-tier lock + long-lived refresh marker pattern so
// that slow discovery IO (PTY ~30 s, HTTP ~316 ms) never blocks UI reads.
//
// Public surface: Cache.Read, Cache.Refresh, Cache.MaybeRefresh, Cache.Prune.
// The Refresher function is injected; the cache manages single-flight
// deduplication, atomic writes, and crash recovery.
package discoverycache

import (
	"context"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"

	"golang.org/x/sync/singleflight"
)

const (
	lockAcquisitionTimeout = 100 * time.Millisecond
	lockPollInterval       = 5 * time.Millisecond
	waitPollInterval       = 250 * time.Millisecond
	stalenessMultiplier    = time.Duration(2)
)

// Cache is the root handle. Root is the base directory (e.g. ~/.cache/fizeau).
// Each Cache instance owns one in-process singleflight.Group; a new Cache per
// process is the normal usage.
type Cache struct {
	Root string
	sf   singleflight.Group
}

// Source describes one cacheable data stream (one file under Root/Tier/Name.json).
type Source struct {
	// Tier is "discovery" or "runtime".
	Tier string
	// Name is the kebab-case source identifier (e.g. "openrouter").
	Name string
	// TTL controls freshness: Read returns Fresh=true when Age < TTL.
	TTL time.Duration
	// RefreshDeadline is the maximum time a refresh is expected to take.
	// Also controls the staleness threshold: 2 × RefreshDeadline.
	RefreshDeadline time.Duration
}

func (s Source) key() string { return s.Tier + "/" + s.Name }

// ReadResult is the output of Cache.Read.
type ReadResult struct {
	// Data is the raw bytes from the cache file; nil if no file exists.
	Data  []byte
	// Age is how long ago the data was written (0 if absent).
	Age   time.Duration
	// Fresh is true when Age < TTL and Data is non-nil.
	Fresh bool
	// Stale is true when Data is nil or Age >= TTL.
	Stale bool
}

// Refresher is the source-fetch function injected by the caller. The cache
// handles single-flight deduplication, the atomic write, and marker lifecycle.
type Refresher func(ctx context.Context) ([]byte, error)

// Read returns cached data without any IO beyond reading the local file.
// It never blocks on network or PTY. If no cache file exists, Data is nil and
// Stale is true. Stale data is always returned without error; the caller
// decides whether to trigger a background refresh.
func (c *Cache) Read(s Source) (ReadResult, error) {
	path := c.dataPath(s)
	data, err := os.ReadFile(path) // #nosec G304
	if errors.Is(err, os.ErrNotExist) {
		return ReadResult{Stale: true}, nil
	}
	if err != nil {
		return ReadResult{}, err
	}
	info, err := os.Stat(path)
	if err != nil {
		// File was just there; best-effort fallback.
		return ReadResult{Data: data, Stale: true}, nil
	}
	age := time.Since(info.ModTime())
	if age < 0 {
		age = 0
	}
	fresh := age < s.TTL
	return ReadResult{
		Data:  data,
		Age:   age,
		Fresh: fresh,
		Stale: !fresh,
	}, nil
}

// Refresh forces a synchronous refresh regardless of TTL. If a refresh is
// already in flight (another goroutine or process), it waits for that refresh
// to complete before returning. Uses in-process singleflight so concurrent
// callers within the same process share one goroutine.
func (c *Cache) Refresh(s Source, fn Refresher) error {
	_, err, _ := c.sf.Do(s.key(), func() (interface{}, error) {
		return nil, c.refreshAndCommit(s, fn)
	})
	return err
}

// MaybeRefresh triggers a background refresh if the data is stale or absent.
// Returns immediately; never blocks the caller. Safe to call on every read hot
// path.
func (c *Cache) MaybeRefresh(s Source, fn Refresher) {
	res, err := c.Read(s)
	if err != nil || res.Fresh {
		return
	}
	go func() {
		_, _, _ = c.sf.Do(s.key(), func() (interface{}, error) {
			return nil, c.refreshAndCommit(s, fn)
		})
	}()
}

// Prune removes data files (and their sidecar lock/marker/tmp files) for
// sources not listed in activeSources. Sources with an active .refreshing
// marker are skipped. Prune acquires the tier-1 lock before removing each
// source's files.
func (c *Cache) Prune(activeSources []Source) error {
	active := make(map[string]bool, len(activeSources))
	for _, s := range activeSources {
		active[s.key()] = true
	}

	return filepath.WalkDir(c.Root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return nil
		}
		if !strings.HasSuffix(d.Name(), ".json") {
			return nil
		}
		rel, rerr := filepath.Rel(c.Root, path)
		if rerr != nil {
			return nil
		}
		parts := strings.SplitN(rel, string(filepath.Separator), 2)
		if len(parts) != 2 {
			return nil
		}
		tier := parts[0]
		name := strings.TrimSuffix(parts[1], ".json")
		if strings.ContainsRune(name, filepath.Separator) {
			return nil // nested dir, skip
		}

		if active[tier+"/"+name] {
			return nil
		}

		s := Source{Tier: tier, Name: name}

		// Skip sources with an active refresh in progress.
		m, _ := readMarker(c.markerPath(s))
		if isMarkerActiveForPrune(m) {
			return nil
		}

		release, lerr := c.acquireLock(s)
		if lerr != nil {
			return nil // can't lock; skip this source
		}
		defer release()

		// Re-check under lock.
		m2, _ := readMarker(c.markerPath(s))
		if isMarkerActiveForPrune(m2) {
			return nil
		}

		_ = os.Remove(c.dataPath(s))
		_ = os.Remove(c.markerPath(s))
		_ = os.Remove(c.tmpPath(s))
		return nil
	})
}

// ---- internal ---------------------------------------------------------------

type claimResult struct {
	claimed bool
	marker  *refreshMarker
}

// claimRefresh implements Algorithm 1 from ADR-012. Must be called with the
// source directory already created (ensured by refreshAndCommit).
func (c *Cache) claimRefresh(s Source) (claimResult, error) {
	release, err := c.acquireLock(s)
	if err != nil {
		return claimResult{}, err
	}
	defer release()

	existing, _ := readMarker(c.markerPath(s))
	if existing != nil {
		if isStale(s, existing) {
			_ = os.Remove(c.markerPath(s))
		} else {
			return claimResult{claimed: false, marker: existing}, nil
		}
	}

	m := &refreshMarker{
		PID:       os.Getpid(),
		StartedAt: time.Now().UTC(),
		Deadline:  time.Now().UTC().Add(s.RefreshDeadline),
	}
	if werr := writeMarker(c.markerPath(s), m); werr != nil {
		return claimResult{}, werr
	}
	return claimResult{claimed: true}, nil
}

// refreshAndCommit implements Algorithm 2 from ADR-012.
func (c *Cache) refreshAndCommit(s Source, fn Refresher) error {
	if err := os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750); err != nil {
		return err
	}

	claim, err := c.claimRefresh(s)
	if err != nil {
		return err
	}
	if !claim.claimed {
		// Another process is refreshing; wait for it.
		return c.waitForRefresh(s, claim.marker)
	}

	// We hold the claim. Run slow IO outside any lock.
	data, fetchErr := fn(context.Background())
	if fetchErr != nil {
		c.releaseMarker(s)
		return fetchErr
	}

	if werr := atomicWrite(c.dataPath(s), data); werr != nil {
		c.releaseMarker(s)
		return werr
	}

	c.releaseMarker(s)
	return nil
}

// waitForRefresh implements Algorithm 3 from ADR-012. Polls until the marker
// disappears or becomes stale, then returns (data has been written).
func (c *Cache) waitForRefresh(s Source, m *refreshMarker) error {
	// Poll until deadline + staleness_threshold or s.RefreshDeadline, whichever first.
	threshold := s.RefreshDeadline * stalenessMultiplier
	absoluteDeadline := m.Deadline.Add(threshold)
	maxWait := time.Now().Add(s.RefreshDeadline)
	if maxWait.Before(absoluteDeadline) {
		absoluteDeadline = maxWait
	}

	for time.Now().Before(absoluteDeadline) {
		time.Sleep(waitPollInterval)
		current, _ := readMarker(c.markerPath(s))
		if current == nil || isStale(s, current) {
			return nil
		}
	}
	return nil // timed out; caller will read whatever is on disk
}

// releaseMarker removes the .refreshing marker under the tier-1 lock, but
// only if our PID is still recorded (guard against PID-reuse races, per §2
// of refreshAndCommit pseudocode in ADR-012).
func (c *Cache) releaseMarker(s Source) {
	release, err := c.acquireLock(s)
	if err != nil {
		return
	}
	defer release()
	m, _ := readMarker(c.markerPath(s))
	if m != nil && m.PID == os.Getpid() {
		_ = os.Remove(c.markerPath(s))
	}
}

// ---- path helpers -----------------------------------------------------------

func (c *Cache) dataPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".json")
}

func (c *Cache) lockPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".lock")
}

func (c *Cache) markerPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".refreshing")
}

func (c *Cache) tmpPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".json.tmp")
}

